@php($attendanceMap = $event->attendanceRecords->mapWithKeys(fn($record)=>[$record->participant_id.'-'.$record->event_day_id.'-'.$record->type=>['recorded_at'=>$record->recorded_at->format('d/m/Y H:i'),'signature_url'=>$record->signature?route('attendance.signature',$record):null]])->all())
<!doctype html><html lang="pt-MZ"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Assinar — {{ $event->name }}</title>@vite(['resources/css/app.css','resources/js/app.js'])</head><body class="min-h-screen bg-stone-950 text-white"><main class="mx-auto max-w-6xl p-5 lg:p-10"><header class="flex justify-between"><div><p class="text-orange-400">MODO DE ASSINATURA</p><h1 class="mt-2 text-3xl font-bold">{{ $event->name }}</h1><p class="text-stone-400">{{ $event->location }} · {{ $event->starts_on->format('d/m/Y') }}</p></div><a class="btn-secondary bg-white text-stone-950" href="{{ route('events.show',$event) }}">Sair</a></header>@if(session('success'))<div class="my-6 rounded-2xl bg-emerald-500 p-5 text-xl font-bold text-white">✓ {{ session('success') }}</div>@endif @if($errors->has('attendance'))<div class="my-6 rounded-2xl border-2 border-amber-300 bg-amber-100 p-5 text-lg font-bold text-amber-950 shadow-lg">{{ $errors->first('attendance') }} @if(session('attendance_can_update'))<div class="mt-2 text-sm font-medium text-amber-900">Se quiser substituir o registo anterior, desenhe novamente a assinatura e clique em “Actualizar presença existente”.</div>@endif</div>@endif @if($errors->has('signature'))<div class="my-6 rounded-2xl border-2 border-red-300 bg-red-100 p-5 text-lg font-bold text-red-950 shadow-lg">{{ $errors->first('signature') }}</div>@endif<div class="mt-8 grid gap-8 xl:grid-cols-[minmax(0,1fr)_380px]"><form method="post" action="{{ route('attendance.store',$event) }}" id="signature-form">@csrf<input type="hidden" name="replace_existing" id="replace-existing" value="{{ session('attendance_can_update') ? '1' : '0' }}"><div class="grid gap-5 md:grid-cols-3"><label class="field dark">Participante<select name="participant_id" id="participant-id" required><option value="">Procure o seu nome</option>@foreach($event->participants as $p)<option value="{{ $p->id }}" @selected((string)$p->id===old('participant_id'))>{{ $p->full_name }}</option>@endforeach</select></label><label class="field dark">Dia<select name="event_day_id" id="event-day-id" required>@foreach($event->days as $day)<option value="{{ $day->id }}" @selected((string)$day->id===old('event_day_id'))>{{ $day->date->format('d/m/Y') }}</option>@endforeach</select></label><label class="field dark">Tipo<select name="type" id="attendance-type"><option value="check_in" @selected(old('type')==='check_in')>Entrada</option>@if($event->requires_check_out)<option value="check_out" @selected(old('type')==='check_out')>Saída</option>@endif</select></label></div><div id="attendance-state" class="mt-5 rounded-2xl border border-stone-700 bg-stone-900/80 p-4 text-sm text-stone-200"><strong class="block text-base text-white">Selecione participante, dia e tipo.</strong><p id="attendance-state-copy" class="mt-1 text-stone-300">O sistema vai indicar automaticamente se esta presença é nova ou se já foi registada.</p><div id="attendance-state-actions" class="mt-3 hidden flex-wrap gap-3"><a id="attendance-preview-link" class="inline-flex min-h-10 items-center justify-center rounded-xl bg-white px-4 font-semibold text-stone-950 transition hover:bg-stone-100" href="#" target="_blank" rel="noopener">Ver assinatura actual</a></div></div><div class="mt-6 rounded-3xl bg-white p-3"><canvas id="signature" class="h-[45vh] w-full touch-none rounded-2xl bg-white" aria-label="Área para desenhar assinatura"></canvas></div><input type="hidden" name="signature" id="signature-data"><div class="mt-5 flex flex-wrap gap-4"><button type="button" id="clear-signature" class="btn-secondary bg-white text-stone-950">Limpar assinatura</button><button id="submit-attendance" class="btn-primary flex-1 text-lg">Confirmar presença</button><button id="update-attendance" type="submit" class="hidden min-h-12 items-center justify-center rounded-xl bg-amber-300 px-5 font-bold text-amber-950 transition hover:bg-amber-400 focus-visible:outline-3 focus-visible:outline-offset-3 focus-visible:outline-amber-300">Actualizar presença existente</button></div></form><aside class="rounded-3xl border border-stone-800 bg-stone-900/70 p-6"><p class="text-xs font-black tracking-[.18em] text-orange-400">CONTROLO RÁPIDO</p><h2 class="mt-3 text-2xl font-bold">Quem já assinou?</h2><p class="mt-2 text-sm leading-6 text-stone-400">Ao mudar o dia e o tipo, a lista abaixo mostra imediatamente quem já tem presença gravada e quem ainda está pendente.</p><div id="attendance-live-list" class="mt-5 space-y-3"></div></aside></div></main><script>const existingAttendance=@json($attendanceMap);const participantSelect=document.querySelector('#participant-id');const daySelect=document.querySelector('#event-day-id');const typeSelect=document.querySelector('#attendance-type');const replaceExisting=document.querySelector('#replace-existing');const stateBox=document.querySelector('#attendance-state');const stateCopy=document.querySelector('#attendance-state-copy');const stateActions=document.querySelector('#attendance-state-actions');const previewLink=document.querySelector('#attendance-preview-link');const submitButton=document.querySelector('#submit-attendance');const updateButton=document.querySelector('#update-attendance');const liveList=document.querySelector('#attendance-live-list');const participantOptions=[...participantSelect.options].filter(option=>option.value);const c=document.querySelector('#signature'),x=c.getContext('2d');let drawing=false,moved=false;function size(){const d=devicePixelRatio||1,r=c.getBoundingClientRect();c.width=r.width*d;c.height=r.height*d;x.scale(d,d);x.lineWidth=3;x.lineCap='round';x.strokeStyle='#111'}size();function point(e){const r=c.getBoundingClientRect(),p=e.touches?e.touches[0]:e;return[p.clientX-r.left,p.clientY-r.top]}function attendanceKey(participantId,dayId,type){return`${participantId}-${dayId}-${type}`}function currentRecord(){if(!participantSelect.value||!daySelect.value||!typeSelect.value)return null;return existingAttendance[attendanceKey(participantSelect.value,daySelect.value,typeSelect.value)]??null}function applyState(){const record=currentRecord();const ready=participantSelect.value&&daySelect.value&&typeSelect.value;if(!ready){stateBox.className='mt-5 rounded-2xl border border-stone-700 bg-stone-900/80 p-4 text-sm text-stone-200';stateBox.querySelector('strong').textContent='Selecione participante, dia e tipo.';stateCopy.textContent='O sistema vai indicar automaticamente se esta presença é nova ou se já foi registada.';stateActions.classList.add('hidden');replaceExisting.value='0';submitButton.textContent='Confirmar presença';submitButton.classList.remove('hidden');updateButton.classList.add('hidden');updateButton.classList.remove('inline-flex');return}if(record){stateBox.className='mt-5 rounded-2xl border border-amber-300 bg-amber-100 p-4 text-sm text-amber-950';stateBox.querySelector('strong').textContent='Esta presença já foi registada.';stateCopy.textContent=`Registada em ${record.recorded_at}. Pode actualizar a assinatura sem repetir a tentativa.`;replaceExisting.value='1';submitButton.classList.add('hidden');updateButton.classList.remove('hidden');updateButton.classList.add('inline-flex');stateActions.classList.remove('hidden');if(record.signature_url){previewLink.href=record.signature_url;previewLink.classList.remove('hidden')}else{previewLink.classList.add('hidden')}}else{stateBox.className='mt-5 rounded-2xl border border-emerald-300 bg-emerald-100 p-4 text-sm text-emerald-950';stateBox.querySelector('strong').textContent='Presença ainda não registada.';stateCopy.textContent='Pode recolher a assinatura normalmente para este participante.';stateActions.classList.add('hidden');replaceExisting.value='0';submitButton.textContent='Confirmar presença';submitButton.classList.remove('hidden');updateButton.classList.add('hidden');updateButton.classList.remove('inline-flex')}}function renderLiveList(){const dayId=daySelect.value,type=typeSelect.value;if(!dayId||!type){liveList.innerHTML='<p class="rounded-2xl border border-stone-800 bg-stone-950/80 p-4 text-sm text-stone-400">Selecione um dia e o tipo para ver a situação dos participantes.</p>';return}liveList.innerHTML=participantOptions.map(option=>{const record=existingAttendance[attendanceKey(option.value,dayId,type)];return`<div class="flex items-center justify-between gap-3 rounded-2xl border ${record?'border-emerald-800 bg-emerald-950/40':'border-stone-800 bg-stone-950/60'} px-4 py-3"><div><p class="font-semibold text-white">${option.textContent}</p>${record?`<p class="mt-1 text-xs text-emerald-200">Assinou em ${record.recorded_at}</p>`:'<p class="mt-1 text-xs text-stone-400">Ainda sem assinatura</p>'}</div><span class="${record?'bg-emerald-100 text-emerald-800':'bg-amber-100 text-amber-800'} inline-flex whitespace-nowrap rounded-full px-2.5 py-1 text-[11px] font-semibold">${record?'Presente':'Pendente'}</span></div>`}).join('')}c.addEventListener('pointerdown',e=>{drawing=true;moved=false;x.beginPath();x.moveTo(...point(e));c.setPointerCapture(e.pointerId)});c.addEventListener('pointermove',e=>{if(!drawing)return;x.lineTo(...point(e));x.stroke();moved=true});c.addEventListener('pointerup',()=>drawing=false);document.querySelector('#clear-signature').onclick=()=>{x.clearRect(0,0,c.width,c.height);moved=false};[participantSelect,daySelect,typeSelect].forEach(element=>element.addEventListener('change',()=>{applyState();renderLiveList();}));document.querySelector('#signature-form').onsubmit=e=>{if(!moved){e.preventDefault();alert('Desenhe a sua assinatura.');return}document.querySelector('#signature-data').value=c.toDataURL('image/png')};applyState();renderLiveList();</script></body></html>
